/// <summary>
/// Number of days after delivery date parameter
/// </summary>
/// <param name = "_numDaysAfterDeliveryDate">Number of days after delivery date</param>
/// <returns>Number of days after delivery date parameter</returns>
[DataMemberAttribute]
public METNumDaysAfterDeliveryDate parmNumDaysAfterDeliveryDate(METNumDaysAfterDeliveryDate _numDaysAfterDeliveryDate = numDaysAfterDeliveryDate)
{
    numDaysAfterDeliveryDate = _numDaysAfterDeliveryDate;
    return numDaysAfterDeliveryDate;
}
